#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_owned_dmx_projection.h"
#include "owned_session_ik_pass.h"
#include <iostream>
#include "graph_exact_equal.h"
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("input fresh output required");auto base=loadGraph(argv[1]);std::array<uint32_t,3>controls{};const std::array<std::array<float,3>,3>positions{{{.25f,-.5f,.125f},{1.25f,0,0},{.875f,0,0}}};for(unsigned i=0;i<3;++i){Element e{};e.type=internString(base,"DmeTransformControl");e.name=internString(base,"owned_selected_control_"+std::to_string(i));e.id.fill(char(-87));std::memcpy(e.id.data(),&i,4);Value v;v.wire.resize(12);std::memcpy(v.wire.data(),positions[i].data(),12);e.attributes.push_back({internString(base,"defaultPosition"),10,{v}});controls[i]=uint32_t(base.elements.size());base.elements.push_back(e);}
 size_t cases=0,executions=0,positionChanges=0;Graph finalGraph;
 for(int phase:{0,3})for(unsigned mask=0;mask<8;++mask){auto selected=controls;for(unsigned i=0;i<3;++i)if(!(mask&(1u<<i)))selected[i]=0xffffffffu;auto expected=base;GraphTransformHierarchy h(expected);SessionAttributeChanges journal;if(phase==0)for(uint32_t i=0;i<expected.elements.size();++i)if(expected.strings[expected.elements[i].type]=="DmeRigIKConstraintOperator")executeSessionIkWithSelectedControlsCandidate(expected,h,i,{0,0,0},selected,&journal);
 RecoveredOwnedDmxReferenceProjectionCandidate<Graph>p(base,[](const std::string&,auto&)->uint32_t{throw std::runtime_error("external resolver");});auto actual=executeOwnedSessionIkPassCandidate(p,[&](uint32_t){return selected;},phase,true);if(actual.executed!=16||actual.skipped||actual.changes.attributes!=journal.attributes)throw std::runtime_error("selected journal/phase");for(const auto&entry:actual.changes.attributes){auto*owner=p.scene.resolve(p.elementHandles.at(entry.first));if(!owner||!(owner->registration.state&0x10)||!(owner->flags&1))throw std::runtime_error("selected dirty owner");if(entry.second=="position")++positionChanges;}
 auto exported=p.exportReferences([](uint32_t,const auto&)->std::string{throw std::runtime_error("external export");});for(size_t i=0;i<expected.elements.size();++i)for(size_t j=0;j<expected.elements[i].attributes.size();++j)for(size_t k=0;k<expected.elements[i].attributes[j].values.size();++k){const auto&e=expected.elements[i].attributes[j].values[k];const auto&a=exported.elements[i].attributes[j].values[k];if(e.wire!=a.wire||e.reference!=a.reference||e.text!=a.text||e.stringIndex!=a.stringIndex)throw std::runtime_error("selected payload preservation");}if(actual.undoRecords.size()!=actual.changes.attributes.size())throw std::runtime_error("selected undo record count");if(replayOwnedIkUndoRecordsCandidate(p,actual.undoRecords,true)!=actual.undoRecords.size()||!graphExactEqualCandidate(p.graph,base))throw std::runtime_error("selected full graph undo");if(replayOwnedIkUndoRecordsCandidate(p,actual.undoRecords,false)!=actual.undoRecords.size()||!graphExactEqualCandidate(p.graph,expected))throw std::runtime_error("selected full graph redo");if(phase==0&&mask==7)finalGraph=exported;p.scene.cleanup({},[](auto&,bool){},[](auto&){});if(p.scene.size()||p.scene.attributes.size()||p.scene.references.nodes.allocationCount())throw std::runtime_error("selected teardown");executions+=actual.executed;++cases;
 }saveGraph(finalGraph,argv[2]);auto reload=loadGraph(argv[2]);validateGraph(reload);if(reload.elements.size()!=base.elements.size()||positionChanges==0)throw std::runtime_error("selected output");std::cout<<"owned_selected_ik_passes="<<cases<<" executions="<<executions<<" position_changes="<<positionChanges<<" payload_phase_dirty_full_graph_undo_redo_reload_teardown=passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
